#!/usr/bin/env python3
"""Generate exact original CoinOption/ProbOption modifiers, no source-stat edits."""
import argparse,json,pathlib,uuid
ROOT=pathlib.Path(__file__).resolve().parents[3];HERE=pathlib.Path(__file__).parent
p=argparse.ArgumentParser();p.add_argument('--output',type=pathlib.Path,default=ROOT/'Games/FantasyCards/Assets/Game/Core/OriginalEquipmentModifiers.cs');args=p.parse_args()
f=json.loads((HERE/'enumtable-observation.json').read_text())['fields'];coin={x[0]:x for x in f['Enum+CoinOption'].values()};prob={x[0]:x for x in f['Enum+ProbOption'].values()}
selection=json.loads((ROOT/'Tools/Data/ClassicCards/selection.json').read_text())['cards'];q=lambda x:json.dumps(x,ensure_ascii=False)
lines=['// Generated by Tools/Data/Restoration/generate-equipment-modifiers.py.','// Exact public DB CoinOption/ProbOption enums; original source rows unchanged.','using System;','namespace FantasyCards.Core','{','    public static class OriginalEquipmentModifiers','    {','        static int[] Values(string id)','        {','            switch(id)','            {'];records=[]
for card in selection:
 c=card['fields']
 if c['Category']!=4:continue
 code=c.get('CoinOption',1);pc=c.get('ProbOption',1);ct=coin[code][1];pt=prob[pc][1];offsets=[0,0,0,0]
 if code!=1:
  group,sign,number=ct.split('_');delta=int(number)*(-1 if sign=='MINUS' else 1)
  for stat in range(3):
   if group=='CO'or group==['AC','DC','HC'][stat]:offsets[stat]=delta
 if pc!=1:
  _,sign,number=pt.split('_');offsets[3]=int(number)*(-1 if sign=='MINUS' else 1)
 records.append({'id':'fm_'+c['ID'],'name':c['Name'],'coinOptionCode':code,'coinOptionType':ct,'probOptionCode':pc,'probOptionType':pt,'attackCoins':offsets[0],'defenseCoins':offsets[1],'healthCoins':offsets[2],'probabilityPercentagePoints':offsets[3]})
 if any(offsets):lines.append('                case '+q('fm_'+c['ID'])+': return new[] { '+', '.join(map(str,offsets))+' };')
lines+=['                default: return null;','            }','        }','        public static int CoinDelta(UnitState unit, OperationStat stat)','        {','            int index = stat == OperationStat.Attack ? 0 : stat == OperationStat.Defense ? 1 : 2;','            int total = unit.extraCoins;','            foreach(var item in unit.equipment) { var values = Values(item.definitionId); if(values != null) total += values[index]; }','            return total;','        }','        public static int ChancePercent(UnitState unit)','        {','            int chance = 50;','            foreach(var item in unit.equipment) { var values = Values(item.definitionId); if(values != null) chance += values[3]; }','            return Math.Max(0, Math.Min(100, chance));','        }','        public static int CoinCount(CoinRule rule, int delta)','        { return Math.Max(0, Math.Min(5, rule.count + delta)); }','    }','}'];args.output.write_text('\n'.join(lines)+'\n')
if args.output.parent==ROOT/'Games/FantasyCards/Assets/Game/Core':
 meta=pathlib.Path(str(args.output)+'.meta')
 if not meta.exists():meta.write_text('fileFormatVersion: 2\nguid: '+uuid.uuid5(uuid.NAMESPACE_URL,'firstgame/restoration/OriginalEquipmentModifiers').hex+'\n')
(HERE/'equipment-modifiers.json').write_text(json.dumps({'revision':'fm-restoration-2026-10-27','cards':records,'scope':'All97 original equipment CoinOption/ProbOption fields; exact signed deltas from public enum table. Count capped0..5 and probability0..100 by the current slice rules; source fields/pixels remain unchanged.'},ensure_ascii=False,indent=2)+'\n')
print('Generated',len(records),'source-checked equipment rows.')
